(function () {
// Zusatzfälle nach Klausurgewichtung, je 6 Antworten
const W=(window.WPRK_LONG=window.WPRK_LONG||[]);
const L=[{"topic": "kauf", "sv": "Verbraucher K kauft beim Elektrohändler E einen Smart-TV. Nach 14 Monaten stellt der Hersteller die Sicherheitsupdates ein; die Streaming-Apps starten nicht mehr. E sagt, Updates seien Sache des Herstellers.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["K hat keine Rechte gegen E, weil der Fernseher bei Übergabe mangelfrei war (§ 434 I).", "Falsch. Bei Waren mit digitalen Elementen wirkt die Aktualisierungspflicht über die Übergabe hinaus."], ["K muss sich an den Hersteller halten, weil nur er die Software verändern kann.", "Falsch. Schuldner ist der Verkäufer; er kann beim Hersteller Rückgriff nehmen."], ["K kann von E Nacherfüllung verlangen, weil E für die Aktualisierungen einstehen muss.", "Richtig. Der Verkäufer schuldet Updates für den Zeitraum, den der Verbraucher erwarten kann. (§ 475b IV Nr. 2)"], ["K kann nur nach §§ 327 ff. gegen den Hersteller vorgehen, weil die Apps digitale Produkte sind.", "Falsch. Für Waren mit digitalen Elementen gilt Kaufrecht (§ 327a III)."], ["K hat nur Rechte, wenn E bei Vertragsschluss eine Update-Garantie übernommen hat.", "Falsch. Die Pflicht folgt aus dem Gesetz."], ["K kann sofort ohne Frist zurücktreten, weil fehlende Updates nie nachgeholt werden können.", "Falsch. Ein Update ist nachholbar; zunächst ist Nacherfüllung zu verlangen."]], "id": "P2-kauf1-0"}, {"topic": "kauf", "sv": "Verbraucherin V kauft beim Händler H eine Smartwatch. H informiert sie per E-Mail über ein verfügbares Sicherheitsupdate und erklärt, was passiert, wenn es nicht installiert wird. V installiert es nicht. Wochen später stürzt die Uhr wegen genau dieser Lücke ständig ab.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["H haftet nicht, weil V das angebotene Update trotz Information nicht installiert hat.", "Richtig. Information und Anleitung lagen vor. (§ 475b V)"], ["V kann Nacherfüllung verlangen, weil die Uhr bei Absturz mangelhaft ist und Verschulden keine Rolle spielt.", "Falsch. Der Verkäufer haftet nicht für Mängel, die allein auf das nicht installierte Update zurückgehen (§ 475b V)."], ["V kann mindern, weil der Händler die Installation selbst hätte vornehmen müssen.", "Falsch. Die Installation obliegt dem Verbraucher nach ordnungsgemäßer Information."], ["V kann zurücktreten, weil H ihr das Update nur per E-Mail und nicht schriftlich angeboten hat.", "Falsch. Eine Schriftform verlangt § 475b nicht."], ["H haftet nur zur Hälfte, weil beide Seiten den Absturz mitverursacht haben (§ 254).", "Falsch. § 475b V schließt die Haftung insoweit ganz aus."], ["V hat Rechte gegen den Hersteller aus § 327f, weil das Update von ihm stammt.", "Falsch. §§ 327 ff. gelten für Waren mit digitalen Elementen nicht."]], "id": "P2-kauf1-1"}, {"topic": "kauf", "sv": "Kunde K kauft beim Fachhändler F ein E-Bike, dessen Motorsteuerung per App eingestellt werden kann. Fahren und Unterstützung funktionieren auch ohne App. Die App selbst stürzt dauernd ab.", "q": "Welche Aussage zur Einordnung ist richtig?", "c": 1, "o": [["Das E-Bike ist stets eine Ware mit digitalen Elementen, weil es eine App gibt.", "Falsch. Entscheidend ist, ob die Ware ihre Funktionen ohne das digitale Element erfüllen kann (§ 327a III)."], ["Für die App gelten die §§ 327 ff., weil das E-Bike auch ohne sie funktioniert.", "Richtig. Kein Fall des § 327a III; die App ist ein eigenes digitales Produkt."], ["Die App ist Teil des Kaufvertrags über das E-Bike, deshalb gilt allein § 434.", "Falsch. Ohne Funktionsnotwendigkeit ist die App eigenständig zu beurteilen."], ["Für die App gilt das Werkvertragsrecht, weil sie programmiert werden musste.", "Falsch. Für digitale Produkte gelten die §§ 327 ff."], ["K hat wegen der App keinerlei Rechte, weil das E-Bike fahrbereit ist.", "Falsch. Die App kann als digitales Produkt eigene Rechte auslösen."], ["K kann wählen, ob er Kaufrecht oder die §§ 327 ff. anwendet.", "Falsch. Ein Wahlrecht gibt es nicht; das Gesetz ordnet zu."]], "id": "P2-kauf1-2"}, {"topic": "kauf", "sv": "Händler H verkauft der Verbraucherin V einen fünf Jahre alten Kleinwagen. Im Formular steht vorgedruckt: „Das Fahrzeug hat altersbedingt Rost an den Schwellern.“ V unterschreibt das Formular am Ende. Später verlangt sie wegen des Rosts Nacherfüllung.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["Der Rost ist kein Mangel, weil V die Klausel mit ihrer Unterschrift akzeptiert hat.", "Falsch. Eine Unterschrift unter dem Gesamtformular genügt nicht."], ["Der Rost ist nie ein Mangel, weil Rost bei Gebrauchtwagen übliche Beschaffenheit ist.", "Falsch. „Nie“: Es kommt auf Alter, Umfang und Vereinbarung an."], ["Die Klausel ist wirksam, weil sie nur eine Tatsache beschreibt und keine Haftung ausschließt.", "Falsch. Sie soll die Sollbeschaffenheit absenken; dafür gelten die Anforderungen des § 476 I 2."], ["V hat keine Rechte, weil vorgedruckte Formularangaben dem gesetzlichen Mangelbegriff vorgehen.", "Falsch. § 476 I ist zwingend; eine Absenkung der Sollbeschaffenheit gelingt nur unter seinen Voraussetzungen."], ["V hat Rechte nur, wenn H den Rost arglistig verschwiegen hat (§ 444).", "Falsch. Arglist ist nicht nötig; schon § 476 I greift."], ["Der Rost ist ein Mangel, weil die Abweichung weder eigens mitgeteilt noch gesondert vereinbart wurde.", "Richtig. Beide Voraussetzungen fehlen. (§ 476 I 2)"]], "id": "P2-kauf1-3"}, {"topic": "kauf", "sv": "Privatmann P verkauft dem Privatmann K sein Motorrad „gekauft wie gesehen, unter Ausschluss jeder Gewährleistung“. P wusste, dass der Motor Öl verliert, und sagte nichts. K fragte nicht danach.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["K hat keine Rechte, weil zwischen Privatleuten jeder Ausschluss wirksam ist.", "Falsch. Bei Arglist greift § 444."], ["K hat keine Rechte, weil er nicht nach dem Motor gefragt hat und P deshalb nichts sagen musste.", "Falsch. Bei erheblichen, nicht erkennbaren Mängeln besteht eine Offenbarungspflicht."], ["Der Ausschluss ist unwirksam, weil § 476 I jede Beschränkung verbietet.", "Falsch. § 476 gilt nur beim Verbrauchsgüterkauf."], ["K hat Rechte nur, wenn er beweist, dass P einen Ölverlust zugesichert hat.", "Falsch. Es geht nicht um eine Garantie, sondern um Arglist."], ["P kann sich nicht auf den Ausschluss berufen, weil er den Mangel arglistig verschwiegen hat.", "Richtig. Zwischen Privaten ist der Ausschluss sonst wirksam. (§ 444)"], ["Der gesamte Kaufvertrag ist nichtig, weil P arglistig gehandelt hat.", "Falsch. Arglist macht nur anfechtbar (§ 123) und sperrt den Ausschluss (§ 444)."]], "id": "P2-kauf1-4"}, {"topic": "kauf", "sv": "Verbraucher K kauft beim Händler H ein Sofa für 1.200 €. H liefert. Nach drei Wochen reißt eine Naht. K bringt das Sofa nicht zurück, sondern verlangt, dass H es bei ihm repariert. H will das Sofa nur in seiner Werkstatt reparieren und verlangt, dass K es auf eigene Kosten bringt.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["K muss das Sofa auf eigene Kosten in die Werkstatt bringen, weil Erfüllungsort der Laden ist.", "Falsch. Die Kosten trägt jedenfalls der Verkäufer (§ 439 II)."], ["H kann die Reparatur verweigern, weil K die Naht durch Gebrauch beschädigt haben könnte.", "Falsch. Innerhalb eines Jahres wird ein Mangel bei Übergabe vermutet (§ 477 I)."], ["K kann sofort zurücktreten, weil H die Reparatur vor Ort verweigert.", "Falsch. Der Ort der Nacherfüllung berechtigt nicht zum sofortigen Rücktritt."], ["H muss die Transportkosten tragen und auf Verlangen vorschießen (§§ 439 II, 475 IV).", "Richtig. Verbrauchsgüterkauf: Vorschussanspruch."], ["H muss ein neues Sofa liefern, weil K das Wahlrecht für Neulieferung hat.", "Falsch. K hat Reparatur verlangt; Neulieferung wählte er nicht."], ["K muss die Transportkosten zahlen, kann sie aber später als Schadensersatz zurückverlangen.", "Falsch. Die Kosten trägt von vornherein der Verkäufer (§ 439 II)."]], "id": "P2-kauf1-5"}, {"topic": "kauf", "sv": "Unternehmer U kauft beim Großhändler G 400 Fliesen und lässt sie von seinem Fliesenleger im Bad eines Kunden verlegen. Danach zeigt sich, dass die Glasur fehlerhaft ist. G liefert neue Fliesen, weigert sich aber, das Herausreißen und Neuverlegen zu bezahlen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["G muss nichts zahlen, weil die Aus- und Einbaukosten nur bei Verbrauchsgüterkäufen ersetzt werden.", "Falsch. § 439 III gilt im allgemeinen Kaufrecht, auch zwischen Unternehmern."], ["G muss nur zahlen, wenn er die fehlerhafte Glasur zu vertreten hat (§ 280 I).", "Falsch. § 439 III ist Teil der verschuldensunabhängigen Nacherfüllung."], ["G muss die Kosten nur tragen, wenn er die Fliesen selbst verlegt hätte.", "Falsch. § 439 III erfasst gerade den Einbau durch den Käufer."], ["U muss sich an den Fliesenleger halten, weil dieser die Fliesen eingebaut hat.", "Falsch. Der Fliesenleger hat ordnungsgemäß gearbeitet; der Mangel liegt in der Kaufsache."], ["G muss nur die Hälfte der Kosten tragen, weil U die Fliesen vor dem Einbau hätte prüfen müssen.", "Falsch. Eine solche Kürzung sieht § 439 III nicht vor; § 377 HGB betrifft die Rüge."], ["G muss U die erforderlichen Aufwendungen für Ausbau und Einbau ersetzen (§ 439 III).", "Richtig. Fliesen wurden ihrer Art und ihrem Zweck gemäß eingebaut."]], "id": "P2-kauf1-6"}, {"topic": "kauf", "sv": "Verbraucher K kauft einen Neuwagen für 25.000 €. Ein Steuergerät ist defekt; der Austausch kostet 300 €. K verlangt die Lieferung eines neuen Fahrzeugs. Ein Neuwagen würde den Händler 4.000 € kosten, weil er den alten nur als Gebrauchtwagen verwerten kann.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Der Händler kann die Neulieferung verweigern und stattdessen den Austausch anbieten.", "Richtig. Krasses Missverhältnis bei geringem Mangel. (§ 439 IV)"], ["K kann frei wählen; der Händler muss das neue Fahrzeug liefern, weil K Verbraucher ist.", "Falsch. Auch beim Verbrauchsgüterkauf gilt § 439 IV."], ["Der Händler kann jede Nacherfüllung verweigern und K auf Minderung verweisen.", "Falsch. Er kann nur die unverhältnismäßige Art verweigern."], ["K kann sofort zurücktreten, weil der Händler die gewählte Art der Nacherfüllung verweigert.", "Falsch. Der Händler darf hier verweigern; K bleibt die andere Art."], ["K muss bei Neulieferung eine Nutzungsentschädigung für das alte Fahrzeug zahlen.", "Falsch. Beim Verbrauchsgüterkauf sind Nutzungen nicht herauszugeben (§ 475 III 1)."], ["Der Händler kann die Neulieferung nur verweigern, wenn der Mangel unerheblich im Sinne des § 323 V ist.", "Falsch. Maßstab ist die Unverhältnismäßigkeit der Kosten (§ 439 IV), nicht § 323 V."]], "id": "P2-kauf1-7"}, {"topic": "kauf", "sv": "Verbraucherin V kauft eine Waschmaschine. Beim zweiten Waschgang läuft Wasser aus. V setzt dem Händler eine Frist; er repariert, doch die Maschine leckt erneut. Ein zweiter Reparaturversuch scheitert ebenfalls.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["V muss dem Händler eine dritte Frist setzen, bevor sie zurücktreten kann.", "Falsch. Nach zwei erfolglosen Versuchen gilt die Nachbesserung als fehlgeschlagen (§ 440 S. 2)."], ["V kann nur mindern, weil der Händler sich ernsthaft um die Reparatur bemüht hat.", "Falsch. Bemühen ändert nichts am Fehlschlagen."], ["V kann ohne weitere Frist zurücktreten, da die Nachbesserung fehlgeschlagen ist.", "Richtig. In der Regel nach dem zweiten erfolglosen Versuch. (§§ 440 S. 2, 323)"], ["V kann nur zurücktreten, wenn der Händler die Undichtigkeit verschuldet hat.", "Falsch. Der Rücktritt ist verschuldensunabhängig."], ["V kann den Kaufpreis nur zurückverlangen, wenn sie die Maschine noch originalverpackt hat.", "Falsch. Eine Originalverpackung ist keine Voraussetzung."], ["V muss sich mit einer Gutschrift begnügen, weil Rückzahlung im Handel unüblich ist.", "Falsch. Der Rücktritt führt zur Rückzahlung (§ 346 I)."]], "id": "P2-kauf1-8"}, {"topic": "kauf", "sv": "Kaufmann U (eingetragener Kaufmann) kauft bei Hersteller H (GmbH) eine Verpackungsmaschine für 50.000 €. Bei Lieferung prüft U sie nicht. Nach sechs Wochen bemerkt er bei der ersten Inbetriebnahme, dass ein offensichtlich verbogener Greifarm nicht funktioniert, und rügt sofort.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["U behält seine Rechte, weil er den Mangel sofort nach der Entdeckung gerügt hat.", "Falsch. Der Mangel war bei ordnungsgemäßer Untersuchung erkennbar; dann ist unverzüglich nach Ablieferung zu rügen."], ["§ 377 HGB gilt nicht, weil U eine Maschine und keine Handelsware gekauft hat.", "Falsch. § 377 HGB gilt für jeden beiderseitigen Handelskauf."], ["U kann die Mängelrechte behalten, weil die Rügefrist nach § 377 HGB zwei Monate beträgt.", "Falsch. Es gilt „unverzüglich“."], ["Die Ware gilt als genehmigt; U hat seine Mängelrechte verloren (§ 377 I, II HGB).", "Richtig. Erkennbarer Mangel, keine unverzügliche Untersuchung und Rüge."], ["U hat seine Rechte verloren, H muss aber die Hälfte der Reparatur zahlen.", "Falsch. Die Genehmigungsfiktion schließt die Mängelrechte aus."], ["§ 377 HGB gilt nur, wenn H den Mangel nicht arglistig verschwiegen hat, und Arglist wird vermutet.", "Falsch. Arglist wird nicht vermutet; ein Anhaltspunkt fehlt."]], "id": "P2-kauf1-9"}, {"topic": "kauf", "sv": "Verbraucher K kauft im Elektromarkt einen Kühlschrank. Elf Monate später fällt der Kompressor aus. Der Händler sagt, K müsse beweisen, dass der Fehler schon beim Kauf vorhanden war.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["K muss beweisen, dass der Mangel bei Übergabe vorlag, weil er Rechte geltend macht.", "Falsch. § 477 I kehrt die Beweislast innerhalb eines Jahres um."], ["Die Vermutung gilt nur sechs Monate; danach muss K beweisen.", "Falsch. Seit 2022 gilt ein Jahr."], ["Die Vermutung hilft K nicht, weil Kompressoren Verschleißteile sind.", "Falsch. Ein Kompressorausfall nach elf Monaten ist kein üblicher Verschleiß."], ["Die Vermutung gilt nur, wenn K den Kühlschrank im Fernabsatz gekauft hat.", "Falsch. Sie gilt für jeden Verbrauchsgüterkauf."], ["Vermutet wird, dass der Mangel bei Übergabe vorlag; der Händler muss das Gegenteil beweisen.", "Richtig. Mangel zeigt sich binnen eines Jahres. (§ 477 I)"], ["K hat keine Rechte mehr, weil die Gewährleistung bei Elektrogeräten ein Jahr beträgt.", "Falsch. Die Verjährungsfrist beträgt zwei Jahre (§ 438 I Nr. 3)."]], "id": "P2-kauf1-10"}, {"topic": "kauf", "sv": "Verbraucherin V kauft einen Saugroboter, dessen Software laut Vertrag drei Jahre lang dauerhaft bereitgestellt wird. Nach 20 Monaten fällt die Kartierfunktion wegen eines Softwarefehlers aus.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["V muss beweisen, dass der Softwarefehler schon bei Übergabe vorlag.", "Falsch. Bei dauerhafter Bereitstellung gilt eine besondere Vermutung (§ 477 II)."], ["Es wird vermutet, dass das digitale Element während der bisherigen Bereitstellung mangelhaft war.", "Richtig. Besondere Vermutung bei dauerhafter Bereitstellung. (§ 477 II)"], ["Die Vermutung des § 477 I hilft V, weil sich der Mangel binnen zwei Jahren gezeigt hat.", "Falsch. § 477 I gilt nur ein Jahr; hier greift § 477 II."], ["V hat keine Rechte mehr, weil Softwarefehler nach einem Jahr nicht mehr geltend gemacht werden können.", "Falsch. Eine solche Grenze gibt es nicht."], ["V hat nur Rechte gegen den Softwarehersteller nach §§ 327 ff.", "Falsch. Ware mit digitalen Elementen: Kaufrecht gegen den Verkäufer."], ["V hat Rechte nur, wenn die Kartierfunktion im Vertrag ausdrücklich genannt war.", "Falsch. Auch objektive Anforderungen sind geschuldet."]], "id": "P2-kauf1-11"}, {"topic": "kauf", "sv": "Möbelhaus M liefert dem Verbraucher K einen Kleiderschrank zur Selbstmontage. Die Montageanleitung ist so fehlerhaft, dass K eine Rückwand falsch einbaut und der Schrank wackelt. Der Schrank selbst ist einwandfrei.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["Es liegt kein Mangel vor, weil die gelieferten Teile einwandfrei sind.", "Falsch. Eine mangelhafte Montageanleitung begründet einen Mangel, wenn sie zur fehlerhaften Montage führt."], ["Der Schrank ist mangelhaft, weil die Montageanleitung fehlerhaft war.", "Richtig. Sogenannte IKEA-Klausel. (§ 434 IV Nr. 2)"], ["K hat nur Rechte, wenn M den Schrank selbst montiert hätte.", "Falsch. Erfasst ist gerade die Selbstmontage durch den Käufer."], ["K trägt das Risiko, weil er die Montage freiwillig selbst übernommen hat.", "Falsch. Das Risiko einer fehlerhaften Anleitung trägt der Verkäufer."], ["K kann nur Schadensersatz verlangen, weil eine Anleitung keine Kaufsache ist.", "Falsch. Die Anleitung gehört zu den Montageanforderungen (§ 434 IV)."], ["Der Schrank ist mangelhaft, aber nur, wenn K den Fehler in der Anleitung nicht hätte erkennen können.", "Falsch. Auf Erkennbarkeit kommt es nicht an."]], "id": "P2-kauf1-12"}, {"topic": "kauf", "sv": "K bestellt bei V „20 Kisten Mineralwasser still“. V liefert 20 Kisten Mineralwasser mit Kohlensäure. K will die Kisten zurückgeben und sofort vom Vertrag zurücktreten.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["K kann sofort zurücktreten, weil V gar nicht geliefert hat, was geschuldet war.", "Falsch. Die Falschlieferung ist ein Mangel; es gilt der Vorrang der Nacherfüllung."], ["K muss das Wasser mit Kohlensäure behalten, weil er die Lieferung angenommen hat.", "Falsch. Die Annahme schließt Mängelrechte nicht aus."], ["Ein Vertrag über Wasser mit Kohlensäure ist durch die Annahme der Lieferung zustande gekommen.", "Falsch. Die Lieferung ist Erfüllungsversuch, kein neues Angebot."], ["K kann nur mindern, weil Wasser mit Kohlensäure gleichwertig ist.", "Falsch. Zuerst kann K Nacherfüllung verlangen."], ["Die Falschlieferung steht einem Sachmangel gleich; K muss zunächst Lieferung des Richtigen verlangen.", "Richtig. Vorrang der Nacherfüllung. (§§ 434 V, 439)"], ["K kann das Wasser behalten und muss nicht zahlen, weil es nicht bestellt war (§ 241a).", "Falsch. § 241a betrifft unbestellte Leistungen, nicht Falschlieferungen auf eine Bestellung."]], "id": "P2-kauf1-13"}, {"topic": "kauf", "sv": "K kauft vom Händler V einen gebrauchten Laptop. Später stellt sich heraus, dass der Laptop einem Leasingunternehmen gehörte, das ihn von K herausverlangt. V wusste davon nichts.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["Es liegt ein Sachmangel vor, weil der Laptop nicht die übliche Beschaffenheit hat.", "Falsch. Das Recht eines Dritten ist ein Rechtsmangel (§ 435)."], ["K hat keine Rechte gegen V, weil V gutgläubig war.", "Falsch. Mängelrechte setzen kein Verschulden voraus."], ["Der Kaufvertrag ist nichtig, weil V nicht Eigentümer war.", "Falsch. Der Verkauf einer fremden Sache ist wirksam."], ["K kann nur gegen das Leasingunternehmen vorgehen, weil es den Laptop herausverlangt.", "Falsch. Ansprüche wegen des Rechtsmangels richten sich gegen V."], ["K hat Rechte nur, wenn er beim Kauf nach dem Eigentum gefragt hat.", "Falsch. Der Verkäufer schuldet die Sache frei von Rechten Dritter (§ 433 I 2)."], ["Es liegt ein Rechtsmangel vor; K hat die Rechte aus § 437 (§ 435).", "Richtig. Ein Dritter kann Rechte an der Sache geltend machen."]], "id": "P2-kauf1-14"}, {"topic": "kauf", "sv": "Verbraucherin V kauft beim Händler H ein Handy, das in der Werbung des Herstellers mit „wasserdicht bis 2 Meter“ beworben wird. Bei H wurde darüber nicht gesprochen. Nach einem kurzen Bad in 1 Meter Tiefe ist das Handy defekt.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["Kein Mangel, weil H selbst nichts zur Wasserdichtigkeit gesagt hat.", "Falsch. Öffentliche Äußerungen des Herstellers prägen die übliche Beschaffenheit (§ 434 III 1 Nr. 2 b)."], ["Kein Mangel, weil Werbung nie Teil des Vertrags wird.", "Falsch. „Nie“: Werbeaussagen des Herstellers sind beachtlich."], ["Ein Mangel liegt vor, weil die Herstellerwerbung die Sollbeschaffenheit prägt.", "Richtig. Herstellerwerbung zählt zur üblichen Beschaffenheit."], ["V hat nur gegen den Hersteller Ansprüche, weil er die Werbung gemacht hat.", "Falsch. Die Mängelrechte richten sich gegen den Verkäufer."], ["V hat Rechte nur, wenn H die Werbung kannte.", "Falsch. Der Verkäufer kann sich nur entlasten, wenn er sie weder kannte noch kennen musste; ein Händler muss bekannte Herstellerwerbung kennen."], ["V hat keine Rechte, weil sie das Handy bewusst ins Wasser gebracht hat.", "Falsch. Gerade das war nach der Werbung möglich."]], "id": "P2-kauf1-15"}, {"topic": "kauf", "sv": "K kauft für 800 € ein gebrauchtes Rennrad, das mangelfrei 1.000 € wert wäre. Wegen eines Haarrisses im Rahmen ist es nur 600 € wert. K setzt erfolglos eine Frist zur Reparatur und erklärt die Minderung.", "q": "Wie viel kann K zurückverlangen?", "c": 2, "o": [["400 €, nämlich die Wertdifferenz zwischen mangelfreiem und mangelhaftem Rad.", "Falsch. Gemindert wird im Verhältnis, nicht um die absolute Differenz (§ 441 III)."], ["200 €, weil das Rad 200 € weniger wert ist als der gezahlte Preis.", "Falsch. Maßstab ist das Verhältnis der Werte, nicht der Vergleich mit dem Preis."], ["320 €, weil der Preis im Verhältnis 600 zu 1.000 auf 480 € sinkt.", "Richtig. 800 € × 600/1.000 = 480 €; zurück 320 €. (§ 441 III)"], ["Nichts, weil K das Rad immer noch günstiger als zum Marktwert gekauft hat.", "Falsch. Die Minderung setzt keinen Verlustgeschäft voraus."], ["400 €, weil die Minderung im Zweifel die Hälfte des Kaufpreises beträgt.", "Falsch. Eine solche Regel gibt es nicht."], ["320 €, aber nur, wenn K das Rad an den Verkäufer zurückgibt.", "Falsch. Bei der Minderung behält der Käufer die Sache."]], "id": "P2-kauf2-0"}, {"topic": "kauf", "sv": "Verbraucherin V kauft einen neuen Föhn für 60 €. Wegen eines Konstruktionsfehlers fängt er beim ersten Gebrauch Feuer; V erleidet Verbrennungen an der Hand. Der Händler H hätte den Fehler nicht erkennen können.", "q": "Welche Ansprüche hat V gegen H?", "c": 5, "o": [["V kann von H Schmerzensgeld verlangen, weil Mängelrechte verschuldensunabhängig sind.", "Falsch. Schadensersatz nach § 437 Nr. 3 setzt Vertretenmüssen voraus."], ["V kann von H Schadensersatz verlangen, weil der Hersteller Erfüllungsgehilfe des H ist (§ 278).", "Falsch. Der Hersteller ist nicht Erfüllungsgehilfe des Händlers."], ["V hat gegen H gar keine Rechte, weil er den Fehler nicht erkennen konnte.", "Falsch. Nacherfüllung, Rücktritt und Minderung bleiben."], ["V kann von H Schadensersatz verlangen, aber nur nach erfolgloser Frist zur Nacherfüllung.", "Falsch. Es fehlt am Vertretenmüssen; zudem ist der Körperschaden nicht nacherfüllbar."], ["V kann den Schaden nur nach dem ProdHaftG von H verlangen, weil er den Föhn in Verkehr gebracht hat.", "Falsch. Der Händler ist grundsätzlich nicht Hersteller im Sinne des § 4 ProdHaftG."], ["V kann Nacherfüllung, Rücktritt oder Minderung, aber keinen Schadensersatz verlangen.", "Richtig. Verschuldensunabhängige Rechte ja, Schadensersatz nein; Ansprüche gegen den Hersteller bleiben."]], "id": "P2-kauf2-1"}, {"topic": "kauf", "sv": "Gastwirt G kauft beim Händler H eine Spülmaschine. Sie fällt wegen eines Mangels aus; G muss für zwei Tage Einweggeschirr für 300 € kaufen. H hätte den Mangel bei der vorgeschriebenen Endkontrolle bemerkt.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["G kann die 300 € nur nach erfolgloser Fristsetzung als Schadensersatz statt der Leistung verlangen.", "Falsch. Es geht um einen Mangelfolgeschaden neben der Leistung; eine Frist ist nicht nötig."], ["G kann die 300 € als Schaden neben der Leistung ohne Fristsetzung verlangen (§§ 437 Nr. 3, 280 I).", "Richtig. Betriebsausfallschaden, vermutetes Vertretenmüssen."], ["G kann die 300 € nur nach §§ 280 II, 286 verlangen, also erst nach einer Mahnung.", "Falsch. Es geht nicht um verspätete, sondern um mangelhafte Leistung."], ["G kann die 300 € nicht verlangen, weil Einweggeschirr keine Aufwendung im Sinne des § 284 ist.", "Falsch. Es ist ersatzfähiger Schaden, keine vergebliche Aufwendung."], ["G kann die 300 € nur verlangen, wenn er zuerst zurücktritt.", "Falsch. Schadensersatz besteht unabhängig vom Rücktritt."], ["G hat keinen Anspruch, weil H den Mangel nicht vorsätzlich verursacht hat.", "Falsch. Fahrlässigkeit genügt (§ 276 I)."]], "id": "P2-kauf2-2"}, {"topic": "kauf", "sv": "K kauft beim Gebrauchtwagenhändler H einen Pkw. Ein Motorschaden zeigt sich; H verweigert ernsthaft und endgültig jede Reparatur. K kauft ein gleichwertiges Fahrzeug bei einem anderen Händler für 1.500 € mehr und gibt das erste zurück.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["K muss H zuerst eine Frist zur Nacherfüllung setzen, sonst bekommt er die 1.500 € nicht.", "Falsch. Die Frist ist bei ernsthafter und endgültiger Verweigerung entbehrlich (§ 281 II)."], ["K kann die 1.500 € nur verlangen, wenn er auf den Rücktritt verzichtet.", "Falsch. Rücktritt und Schadensersatz sind kombinierbar (§ 325)."], ["K hat keinen Anspruch, weil die Mehrkosten eines Deckungskaufs nie ersatzfähig sind.", "Falsch. Sie sind typischer Schadensersatz statt der Leistung."], ["K kann zurücktreten und daneben 1.500 € Schadensersatz statt der Leistung fordern.", "Richtig. Frist entbehrlich, Vertretenmüssen wird vermutet. (§§ 281 II, 325)"], ["K kann die 1.500 € verlangen, muss sich aber den halben Betrag wegen § 254 anrechnen lassen.", "Falsch. Ein Mitverschulden ist nicht ersichtlich."], ["K kann nur mindern, weil er das Fahrzeug bereits benutzt hat.", "Falsch. Die Nutzung schließt weder Rücktritt noch Schadensersatz aus."]], "id": "P2-kauf2-3"}, {"topic": "kauf", "sv": "K kauft beim Händler H einen Wohnwagen für 18.000 € und lässt für 2.000 € eine Markise anbringen, die nur an diesen Wohnwagen passt. Wegen eines erheblichen Mangels tritt K nach erfolgloser Frist zurück. H hat den Mangel zu vertreten.", "q": "Was kann K wegen der Markise verlangen?", "c": 0, "o": [["K kann statt Schadensersatz die 2.000 € als vergebliche Aufwendungen verlangen (§ 284).", "Richtig. Im Vertrauen auf den Erhalt der Leistung gemacht, billigerweise."], ["Nichts, weil die Markise nicht Teil des Kaufvertrags war.", "Falsch. Gerade deshalb kommt Aufwendungsersatz in Betracht."], ["K kann die 2.000 € nur verlangen, wenn H den Mangel vorsätzlich verursacht hat.", "Falsch. Vertretenmüssen genügt; Fahrlässigkeit reicht."], ["K kann die 2.000 € zusätzlich zum vollen Schadensersatz statt der Leistung verlangen.", "Falsch. § 284 gilt „anstelle“ des Schadensersatzes statt der Leistung."], ["K kann die 2.000 € nach § 346 vom Verkäufer zurückverlangen, weil der Rücktritt alles rückabwickelt.", "Falsch. § 346 betrifft nur die ausgetauschten Leistungen."], ["K kann nichts verlangen, weil er nach dem Rücktritt keine Rechte mehr hat.", "Falsch. Der Rücktritt schließt Ersatzansprüche nicht aus (§ 325)."]], "id": "P2-kauf2-4"}, {"topic": "kauf", "sv": "Verbraucher K kauft am 1. März 2024 einen neuen Rasenmäher. Am 15. Januar 2026 zeigt sich ein Getriebeschaden, den K sofort meldet. Er verlangt am 1. Mai 2026 Nacherfüllung; der Händler beruft sich auf Verjährung.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["Der Anspruch ist seit dem 1. März 2026 verjährt (§ 438 I Nr. 3, II).", "Falsch. § 475e III verlängert beim Verbrauchsgüterkauf."], ["Der Anspruch verjährt erst Ende 2027, weil die Regelverjährung gilt (§§ 195, 199).", "Falsch. Für Mängelansprüche gilt § 438."], ["Der Anspruch ist verjährt, weil K den Mangel nicht binnen zwei Monaten schriftlich gerügt hat.", "Falsch. Eine Rügefrist trifft Verbraucher nicht."], ["Der Anspruch ist nicht verjährt, weil die Frist mit der Entdeckung des Mangels neu beginnt.", "Falsch. Die Entdeckung ist kein Neubeginn."], ["Nicht verjährt, weil die Verjährung frühestens am 15. Mai 2026 eintritt.", "Richtig. Mangel innerhalb der Frist gezeigt: vier Monate nach erstem Auftreten. (§ 475e III)"], ["Der Anspruch verjährt erst zwei Jahre nach dem Auftreten des Mangels, also im Januar 2028.", "Falsch. Die Verlängerung beträgt vier Monate."]], "id": "P2-kauf2-5"}, {"topic": "kauf", "sv": "Verbraucherin V lässt sich am 1. Juni 2026 eine Kaffeemaschine reparieren, die sie im Vorjahr gekauft hat; der Verkäufer nimmt sie dafür am 1. Juni zurück und gibt sie am 1. Juli repariert zurück. Die zweijährige Gewährleistungsfrist würde regulär im März 2027 ablaufen.", "q": "Welche Aussage zur Verjährung ist richtig?", "c": 1, "o": [["Die Verjährung beginnt mit der Rückgabe neu und läuft bis Juli 2028.", "Falsch. Ein Neubeginn ist nicht vorgesehen; es gibt eine Ablaufhemmung."], ["Die Verjährung tritt nicht vor zwei Monaten nach der Rückgabe ein.", "Richtig. Ablaufhemmung bei Nacherfüllung. (§ 475e IV)"], ["Die Reparatur hat keinen Einfluss auf die Verjährung.", "Falsch. § 475e IV regelt eine Ablaufhemmung."], ["Die Verjährung ist während der Reparatur um einen Monat gehemmt und läuft dann sechs Monate weiter.", "Falsch. Die Regelung lautet: zwei Monate nach Übergabe der nachgebesserten Ware."], ["Die Verjährung endet mit der Rückgabe der reparierten Maschine.", "Falsch. Die Rückgabe beendet die Verjährung nicht."], ["Die Gewährleistungsfrist verlängert sich um ein volles Jahr.", "Falsch. Eine solche Verlängerung gibt es nicht."]], "id": "P2-kauf2-6"}, {"topic": "kauf", "sv": "Unternehmer U aus München kauft bei Hersteller H in Hamburg 30 Bürostühle. Auf Verlangen des U schickt H sie per Spedition. Unterwegs werden die Stühle bei einem unverschuldeten Unfall zerstört.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["U muss nicht zahlen, weil die Gefahr erst mit der Übergabe in München übergeht (§ 446).", "Falsch. Beim Versendungskauf geht § 447 I vor."], ["U muss nicht zahlen, weil § 475 II die Anwendung des § 447 ausschließt.", "Falsch. § 475 II gilt nur beim Verbrauchsgüterkauf."], ["U muss zahlen, weil die Preisgefahr mit Übergabe an die Spedition übergegangen ist (§ 447 I).", "Richtig. Versendungskauf zwischen Unternehmern."], ["U muss zahlen, H aber erneut liefern, weil Bürostühle Gattungsware sind.", "Falsch. Mit Übergabe an die Spedition ist die Schuld konkretisiert."], ["U muss nur zahlen, wenn H die Spedition sorgfältig ausgewählt hat.", "Falsch. Auf Auswahlverschulden kommt es für die Preisgefahr nicht an."], ["U muss zahlen, kann aber von H Schadensersatz verlangen, weil die Spedition Erfüllungsgehilfin des H ist.", "Falsch. Beim Versendungskauf ist die Transportperson nicht Erfüllungsgehilfe des Verkäufers."]], "id": "P2-kauf2-7"}, {"topic": "kauf", "sv": "Studentin S bestellt beim Online-Händler O einen Monitor. O beauftragt einen Paketdienst. Das Paket geht auf dem Transport verloren.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["S muss zahlen, weil die Gefahr mit Übergabe an den Paketdienst auf sie übergegangen ist (§ 447 I).", "Falsch. Beim Verbrauchsgüterkauf gilt § 447 I grundsätzlich nicht (§ 475 II)."], ["S muss zahlen, weil sie die Versendung gewünscht hat.", "Falsch. Der Wunsch genügt nicht; § 475 II verlangt, dass der Verbraucher den Transporteur selbst beauftragt."], ["S muss die Hälfte zahlen, weil keine Partei den Verlust verschuldet hat.", "Falsch. Eine Teilung gibt es nicht."], ["S muss nicht zahlen; O trägt das Versandrisiko, weil § 447 I nicht anwendbar ist (§ 475 II).", "Richtig. Gefahr geht erst mit Übergabe an S über (§ 446)."], ["S muss nicht zahlen, aber nur, wenn O den Paketdienst schlecht ausgewählt hat.", "Falsch. Auf Auswahlverschulden kommt es nicht an."], ["S muss zahlen, kann aber vom Paketdienst Schadensersatz verlangen.", "Falsch. S muss schon nicht zahlen."]], "id": "P2-kauf2-8"}, {"topic": "kauf", "sv": "Verbraucher K kauft im Laden eine Kamera. Der Verkäufer V sagt: „Ich garantiere Ihnen, dass die Kamera wasserdicht bis 10 Meter ist.“ Bei 5 Metern dringt Wasser ein. Im Vertrag steht: „Gewährleistung ausgeschlossen“.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["K hat keine Rechte, weil die Gewährleistung wirksam ausgeschlossen ist.", "Falsch. Bei übernommener Garantie kann sich V nicht auf den Ausschluss berufen (§ 444); zudem § 476."], ["K hat nur Rechte, wenn V die Undichtigkeit kannte.", "Falsch. Kenntnis ist bei einer Beschaffenheitsgarantie nicht nötig."], ["K hat Rechte nur gegen den Hersteller, weil nur er Garantien abgeben kann.", "Falsch. Auch der Verkäufer kann eine Garantie übernehmen (§ 443)."], ["Der gesamte Vertrag ist nichtig, weil der Ausschluss gegen § 476 verstößt.", "Falsch. Nur der Ausschluss ist unwirksam."], ["K kann nur mindern, weil die Kamera an Land weiter funktioniert.", "Falsch. Zuerst kann K Nacherfüllung verlangen."], ["V kann sich nicht auf den Ausschluss berufen; K hat die Rechte aus § 437.", "Richtig. Garantie (§ 444) und Verbrauchsgüterkauf (§ 476 I)."]], "id": "P2-kauf2-9"}, {"topic": "kauf", "sv": "Hersteller H gewährt auf seine Waschmaschinen eine „Haltbarkeitsgarantie: 5 Jahre volle Funktionsfähigkeit“. Nach drei Jahren fällt die Pumpe bei Kundin K aus. H meint, K müsse beweisen, dass sie die Maschine richtig benutzt hat.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Es wird vermutet, dass der Ausfall einen Garantiefall begründet.", "Richtig. Gesetzliche Vermutung bei der Haltbarkeitsgarantie. (§ 443 II)"], ["K muss beweisen, dass sie die Maschine sachgemäß benutzt hat.", "Falsch. § 443 II enthält eine Vermutung zugunsten des Käufers."], ["Die Garantie ist unwirksam, weil sie länger als die gesetzliche Gewährleistung läuft.", "Falsch. Garantien dürfen darüber hinausgehen."], ["K hat nur Rechte gegen den Händler, weil die Garantie dessen Gewährleistung verlängert.", "Falsch. Die Herstellergarantie richtet sich gegen den Hersteller."], ["Die Vermutung gilt nur für die ersten zwei Jahre der Garantiezeit.", "Falsch. Sie gilt für die gesamte Geltungsdauer der Garantie."], ["K hat keine Rechte, weil Pumpen Verschleißteile sind.", "Falsch. Eine Haltbarkeitsgarantie umfasst gerade die Funktionsfähigkeit."]], "id": "P2-kauf2-10"}, {"topic": "kauf", "sv": "Verbraucher K kauft beim Händler H ein Sofa. Bei der Lieferung sieht K einen deutlichen Riss im Bezug und nimmt das Sofa trotzdem ohne Vorbehalt an. Zwei Wochen später verlangt er Nacherfüllung.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["K hat seine Rechte verloren, weil er den Riss bei Übergabe kannte (§ 442).", "Falsch. § 442 betrifft die Kenntnis bei Vertragsschluss, nicht bei Übergabe."], ["K hat seine Rechte verloren, weil er nicht unverzüglich nach § 377 HGB gerügt hat.", "Falsch. § 377 HGB gilt nur zwischen Kaufleuten."], ["K hat seine Rechte verloren, weil die vorbehaltlose Annahme ein Verzicht ist.", "Falsch. Ein Verzicht liegt in der bloßen Annahme nicht."], ["K hat nur noch Anspruch auf Minderung, weil er den Mangel bei Übergabe kannte.", "Falsch. Eine solche Beschränkung kennt das BGB nicht."], ["K kann Nacherfüllung verlangen; die Kenntnis bei Übergabe schadet nicht.", "Richtig. Maßgeblich für § 442 ist der Vertragsschluss."], ["K kann nur Nacherfüllung verlangen, wenn er den Riss binnen 14 Tagen schriftlich angezeigt hat.", "Falsch. Eine solche Anzeigefrist gibt es nicht."]], "id": "P2-kauf2-11"}, {"topic": "kauf", "sv": "Elektronikhändler E verkauft an Verbraucher K ein neues Notebook, das schon bei Lieferung an E mangelhaft war. E repariert es auf eigene Kosten und will die Kosten von seinem Lieferanten L zurück.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["E kann nichts verlangen, weil er gegenüber K freiwillig repariert hat.", "Falsch. E war zur Nacherfüllung verpflichtet."], ["E kann die Kosten nur verlangen, wenn L den Mangel verschuldet hat.", "Falsch. Der Aufwendungsersatz nach § 445a ist verschuldensunabhängig."], ["E muss sich an den Hersteller halten, weil L nur Zwischenhändler ist.", "Falsch. Rückgriff erfolgt in der Lieferkette, also gegen L."], ["E kann von L die Aufwendungen ersetzt verlangen, die er gegenüber K trug.", "Richtig. Unternehmerrückgriff, Mangel lag schon bei Übergabe an E vor. (§ 445a I)"], ["E kann nur den Kaufpreis des Notebooks zurückverlangen, nicht die Reparaturkosten.", "Falsch. § 445a I erfasst gerade die Aufwendungen."], ["E kann von L nur fordern, wenn K das Notebook im Fernabsatz gekauft hat.", "Falsch. Der Vertriebsweg spielt keine Rolle."]], "id": "P2-kauf2-12"}, {"topic": "kauf", "sv": "Verbraucherin V kauft beim Händler H einen E-Scooter. Nach zwei Wochen fällt der Akku aus. V teilt H den Mangel mit und bittet um Reparatur. H reagiert vier Wochen lang nicht, obwohl eine Reparatur in einer Woche möglich wäre. V erklärt den Rücktritt, ohne eine ausdrückliche Frist gesetzt zu haben.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["Der Rücktritt ist unwirksam, weil V H keine ausdrückliche Frist gesetzt hat (§ 323 I).", "Falsch. Beim Verbrauchsgüterkauf genügt der Ablauf einer angemessenen Frist ab der Mitteilung (§ 475d I Nr. 1)."], ["Der Rücktritt ist unwirksam, weil der Mangel unerheblich ist.", "Falsch. Ein Akkuausfall beim E-Scooter ist erheblich."], ["Wirksam: Seit der Mangelmitteilung ist eine angemessene Frist verstrichen.", "Richtig. Keine ausdrückliche Fristsetzung nötig. (§ 475d I Nr. 1)"], ["Der Rücktritt ist wirksam, aber nur, weil H den Mangel verschuldet hat.", "Falsch. Der Rücktritt ist verschuldensunabhängig."], ["V kann nur mindern, weil sie den Scooter zwei Wochen benutzt hat.", "Falsch. Die Nutzung schließt den Rücktritt nicht aus."], ["Der Rücktritt ist erst nach zwei erfolglosen Reparaturversuchen möglich.", "Falsch. Hier fand gar keine Nacherfüllung statt; § 475d I Nr. 1 greift."]], "id": "P2-kauf2-13"}, {"topic": "kauf", "sv": "Verbraucher K kauft beim Händler H eine neue Spülmaschine. Nach sechs Monaten fällt sie aus. H liefert eine neue Maschine und verlangt von K Ersatz für die sechs Monate Nutzung der alten.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["K muss Nutzungsersatz leisten, weil er die alte Maschine sechs Monate genutzt hat (§ 346 I).", "Falsch. Beim Verbrauchsgüterkauf sind Nutzungen bei Ersatzlieferung nicht herauszugeben (§ 475 III 1)."], ["K muss die Hälfte des Kaufpreises als Nutzungsersatz zahlen.", "Falsch. Er schuldet gar keinen Nutzungsersatz."], ["K muss Nutzungsersatz leisten, weil die neue Maschine länger halten wird als die alte.", "Falsch. Ein Wertausgleich ist beim Verbrauchsgüterkauf ausgeschlossen."], ["K muss nichts zahlen, aber nur, weil H den Mangel verschuldet hat.", "Falsch. Auf Verschulden kommt es nicht an."], ["K schuldet keinen Nutzungsersatz; er gibt nur die alte Maschine zurück.", "Richtig. Rückgewähr der mangelhaften Sache nach § 439 VI, aber keine Nutzungen (§ 475 III 1). (§§ 439 VI, 475 III 1)"], ["K darf die alte Maschine behalten, weil der Händler sie selbst abholen müsste.", "Falsch. Der Verkäufer kann die mangelhafte Sache zurückverlangen (§ 439 V)."]], "id": "P2-kauf2-14"}, {"topic": "kauf", "sv": "Gebrauchtwagenhändler H verkauft dem Verbraucher K einen acht Jahre alten Kombi. In den AGB steht: „Die Verjährung der Mängelansprüche beträgt bei Gebrauchtwagen ein Jahr ab Übergabe.“ K wurde darauf vor Vertragsschluss eigens hingewiesen, und die Verkürzung wurde gesondert vereinbart. Nach 14 Monaten zeigt sich ein Getriebeschaden, der schon bei Übergabe angelegt war.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["Die Verkürzung ist unwirksam, weil beim Verbrauchsgüterkauf stets zwei Jahre gelten.", "Falsch. Bei gebrauchten Sachen ist eine Verkürzung auf ein Jahr zulässig (§ 476 II)."], ["Die Verkürzung ist unwirksam, weil Verjährungsfristen nie durch AGB verkürzt werden dürfen.", "Falsch. „Nie“: § 476 II lässt sie unter Voraussetzungen zu."], ["K kann trotzdem Nacherfüllung verlangen, weil der Mangel schon bei Übergabe angelegt war.", "Falsch. Auch solche Mängel verjähren; die Einrede greift."], ["Die Verkürzung gilt, aber nur für Mängel, die K bei Übergabe hätte erkennen können.", "Falsch. Sie gilt für alle Mängelansprüche."], ["Die Verkürzung ist nur wirksam, wenn K einen Preisnachlass erhalten hat.", "Falsch. Ein Preisnachlass ist keine Voraussetzung."], ["Die Verkürzung auf ein Jahr ist bei Gebrauchtwagen zulässig; der Anspruch ist verjährt.", "Richtig. Eigens mitgeteilt und gesondert vereinbart. (§ 476 II)"]], "id": "P2-kauf3-0"}, {"topic": "kauf", "sv": "Verbraucherin V kauft im Online-Shop eine „neue“ Espressomaschine. Geliefert wird ein Rückläufer mit Gebrauchsspuren, der technisch einwandfrei ist.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Die Maschine ist mangelhaft, weil sie nicht die vereinbarte Beschaffenheit „neu“ hat (§ 434 II).", "Richtig. Subjektive Anforderung: Neuware."], ["Die Maschine ist mangelfrei, weil sie technisch einwandfrei funktioniert.", "Falsch. „Neu“ ist eine vereinbarte Beschaffenheit."], ["V kann nur widerrufen, Mängelrechte hat sie nicht.", "Falsch. Widerruf und Mängelrechte bestehen nebeneinander."], ["V muss die Maschine behalten, weil Rückläufer im Online-Handel üblich sind.", "Falsch. Üblichkeit ändert die Vereinbarung nicht."], ["Es liegt ein Rechtsmangel vor, weil die Maschine schon einem anderen Kunden gehörte.", "Falsch. Der Vorbesitz begründet hier keinen Rechtsmangel, sondern einen Sachmangel."], ["V hat Rechte nur, wenn der Händler die Gebrauchsspuren arglistig verschwiegen hat.", "Falsch. Mängelrechte setzen keine Arglist voraus."]], "id": "P2-kauf3-1"}, {"topic": "kauf", "sv": "K kauft beim Händler H einen gebrauchten Transporter „mit 85.000 km Laufleistung“. Tatsächlich ist der Tacho manipuliert, die Laufleistung beträgt 190.000 km. Ein anderer gleichwertiger Transporter ist nicht zu beschaffen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["K muss H zuerst eine Frist zur Nacherfüllung setzen, bevor er zurücktreten kann.", "Falsch. Die Nacherfüllung ist unmöglich; die Frist ist entbehrlich (§ 326 V)."], ["K kann nur mindern, weil der Transporter fahrbereit ist.", "Falsch. Die Abweichung ist erheblich; der Rücktritt ist möglich."], ["K kann ohne Fristsetzung zurücktreten, weil die Nacherfüllung unmöglich ist.", "Richtig. Unbehebbarer Mangel beim Stückkauf. (§§ 437 Nr. 2, 326 V)"], ["K hat keine Rechte, wenn H die Manipulation nicht kannte.", "Falsch. Rücktritt und Minderung sind verschuldensunabhängig."], ["K kann vom Händler die Reparatur des Tachos verlangen; damit ist der Mangel behoben.", "Falsch. Die tatsächliche Laufleistung lässt sich nicht beheben."], ["K kann zurücktreten, muss aber zusätzlich wegen Täuschung anfechten.", "Falsch. Der Rücktritt braucht keine Anfechtung."]], "id": "P2-kauf3-2"}, {"topic": "kauf", "sv": "K kauft beim Händler H für 30.000 € einen Neuwagen. Am Heck ist ein kaum sichtbarer Lackkratzer; die Beseitigung kostet 120 €. K setzt eine Frist, H repariert nicht. K will zurücktreten.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["K kann zurücktreten, weil jeder Mangel an einem Neuwagen erheblich ist.", "Falsch. Auch beim Neuwagen gilt die Erheblichkeitsschwelle."], ["Kein Rücktritt, weil der Mangel unerheblich ist; Minderung bleibt möglich.", "Richtig. 120 € bei 30.000 € liegt weit unter der Erheblichkeitsschwelle. (§§ 323 V 2, 441 I 2)"], ["K kann zurücktreten, weil H die Frist hat verstreichen lassen.", "Falsch. Der Fristablauf macht den Mangel nicht erheblich."], ["K hat gar keine Rechte, weil der Kratzer unerheblich ist.", "Falsch. Nacherfüllung und Minderung bleiben."], ["K kann großen Schadensersatz verlangen, weil H die Frist nicht genutzt hat.", "Falsch. Großer Schadensersatz scheitert ebenfalls an der Unerheblichkeit (§ 281 I 3)."], ["K kann zurücktreten, wenn er dem Händler eine zweite Frist setzt.", "Falsch. Weitere Fristen ändern an der Unerheblichkeit nichts."]], "id": "P2-kauf3-3"}, {"topic": "kauf", "sv": "Verbraucher K kauft beim Händler H einen Drucker. Er setzt dem Händler wegen eines Defekts eine Frist und lässt den Drucker nach Ablauf von einem Fachbetrieb für 90 € reparieren. Nun verlangt er die 90 €.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["K bekommt die 90 € nicht, weil das Kaufrecht keine Selbstvornahme kennt.", "Falsch. Nach erfolglosem Fristablauf kann K die Kosten als Schadensersatz statt der Leistung verlangen."], ["K bekommt die 90 € nur, wenn H die Reparatur ausdrücklich verweigert hat.", "Falsch. Der erfolglose Fristablauf genügt (§ 281 I)."], ["K bekommt die 90 € nach § 637 analog, weil das Werkvertragsrecht hier gilt.", "Falsch. Es gilt Kaufrecht; Grundlage ist § 281."], ["K bekommt nur die Hälfte, weil er die Reparatur nicht mit H abgestimmt hat.", "Falsch. Eine Abstimmung ist nach Fristablauf nicht nötig."], ["90 € Schadensersatz statt der Leistung; das Verschulden wird vermutet.", "Richtig. Frist abgelaufen, Vertretenmüssen wird vermutet. (§§ 437 Nr. 3, 281)"], ["K bekommt die 90 € nur, wenn er den Drucker zuvor an H zurückgeschickt hat.", "Falsch. Eine Rücksendung ist keine Voraussetzung."]], "id": "P2-kauf3-4"}, {"topic": "kauf", "sv": "Kaufmann K kauft beim Großhändler G 1.000 Glühbirnen. Bei Lieferung prüft K Stichproben, ohne Befund. Nach zwei Monaten zeigt sich, dass ein Viertel der Birnen einen versteckten Fehler hat. K rügt drei Wochen nach Entdeckung.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["K behält seine Rechte, weil der Mangel versteckt war und er Stichproben gemacht hat.", "Falsch. Bei versteckten Mängeln muss unverzüglich nach Entdeckung gerügt werden (§ 377 III HGB)."], ["K behält seine Rechte, weil die Rügefrist für versteckte Mängel einen Monat beträgt.", "Falsch. Eine Monatsfrist gibt es nicht."], ["K hat seine Rechte verloren, weil er alle 1.000 Birnen hätte prüfen müssen.", "Falsch. Stichproben genügen; der Fehler war versteckt."], ["K hat seine Rechte verloren, weil er nach der Entdeckung nicht unverzüglich gerügt hat.", "Richtig. Drei Wochen sind nicht unverzüglich. (§ 377 III HGB)"], ["§ 377 HGB gilt nicht, weil K die Birnen weiterverkaufen wollte.", "Falsch. Gerade beim Handelskauf gilt § 377 HGB."], ["K behält seine Rechte, weil der Großhändler den Mangel kannte und Arglist vermutet wird.", "Falsch. Arglist wird nicht vermutet."]], "id": "P2-kauf3-5"}, {"topic": "kauf", "sv": "Verbraucherin V kauft beim Möbelhändler M eine Couch für 2.000 €. M liefert sie aufgebaut. Eine Woche später bricht ein Fuß ab, weil M ihn beim Aufbau falsch angeschraubt hat.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["Kein Mangel, weil die Couch selbst fehlerfrei ist und nur der Aufbau falsch war.", "Falsch. Eine unsachgemäße Montage durch den Verkäufer ist ein Sachmangel (§ 434 IV Nr. 1)."], ["Die Couch ist mangelhaft, weil die übernommene Montage unsachgemäß war.", "Richtig. Montagemangel. (§ 434 IV Nr. 1)"], ["V hat Ansprüche nur aus einem gesonderten Werkvertrag über den Aufbau.", "Falsch. Die Montage ist Teil der kaufvertraglichen Pflicht (§ 434 IV)."], ["V hat keine Rechte, weil sie den Aufbau sofort hätte prüfen müssen.", "Falsch. Eine Prüfpflicht trifft Verbraucher nicht."], ["V kann nur Schadensersatz verlangen, weil der Fuß durch die Montage beschädigt wurde.", "Falsch. Es bestehen die Rechte aus § 437, zuerst Nacherfüllung."], ["V hat Rechte nur, wenn sie für den Aufbau extra bezahlt hat.", "Falsch. Auch eine im Preis enthaltene Montage ist erfasst."]], "id": "P2-kauf3-6"}, {"topic": "kauf", "sv": "K bestellt beim Händler V 50 Flaschen Wein. V liefert nur 40 Flaschen und stellt 50 in Rechnung.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["K muss die volle Rechnung zahlen und kann nur die restlichen Flaschen nachfordern.", "Falsch. Bis zur vollständigen Lieferung kann K die Gegenleistung teilweise zurückhalten (§ 320)."], ["Der Vertrag ist über 40 Flaschen zustande gekommen, weil K die Lieferung angenommen hat.", "Falsch. Die Annahme ändert den Vertrag nicht."], ["K kann sofort vom ganzen Vertrag zurücktreten, weil V zu wenig geliefert hat.", "Falsch. Zuerst ist Nacherfüllung zu verlangen; zudem gilt § 323 V 1."], ["K hat keine Rechte, weil eine Zuweniglieferung kein Mangel ist.", "Falsch. Die Menge gehört zur vereinbarten Beschaffenheit (§ 434 II 2)."], ["Die Zuweniglieferung ist ein Sachmangel; K kann 10 Flaschen nachfordern.", "Richtig. Seit 2022 ist die Menge Teil der vereinbarten Beschaffenheit (§ 434 II 2); die Zuweniglieferung ist damit selbst ein Sachmangel."], ["K kann nur mindern, weil sich Wein nicht nachliefern lässt.", "Falsch. Wein ist Gattungsware und nachlieferbar."]], "id": "P2-kauf3-7"}, {"topic": "kauf", "sv": "Verbraucherin V kauft im Laden eine Jacke. Zu Hause gefällt sie ihr nicht mehr. Die Jacke ist mangelfrei. Der Laden bietet freiwillig einen Umtausch gegen Gutschein an.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["V hat keine gesetzlichen Rechte; der Umtausch gegen Gutschein ist Kulanz des Ladens.", "Richtig. Kein Mangel, kein Widerrufsrecht."], ["V kann die Jacke binnen 14 Tagen widerrufen und den Kaufpreis zurückverlangen.", "Falsch. Im Ladengeschäft besteht kein gesetzliches Widerrufsrecht."], ["V kann vom Vertrag zurücktreten, weil die Jacke nicht ihren Vorstellungen entspricht.", "Falsch. Ein Rücktritt setzt einen Mangel oder ein vereinbartes Rücktrittsrecht voraus."], ["V kann den Kaufvertrag wegen Eigenschaftsirrtums anfechten.", "Falsch. Ein Geschmacksirrtum ist ein unbeachtlicher Motivirrtum."], ["V hat einen gesetzlichen Anspruch auf Umtausch gegen eine andere Jacke.", "Falsch. Ein gesetzliches Umtauschrecht gibt es nicht."], ["V kann Nacherfüllung verlangen, weil die Jacke nicht ihren Erwartungen entspricht.", "Falsch. Ohne Mangel keine Nacherfüllung."]], "id": "P2-kauf3-8"}, {"topic": "kauf", "sv": "Händler H verkauft dem Verbraucher K einen Laptop. K soll das Gerät nach Kaufvertrag „selbst im Laden abholen“. Am Abholtag fällt das Gerät dem Verkäufer kurz vor der Übergabe aus der Hand und hat danach einen Displaysprung. K nimmt es trotzdem mit.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["Kein Mangel, weil der Schaden erst bei der Übergabe entstanden ist.", "Falsch. Maßgeblich ist der Gefahrübergang; der Schaden entstand vor der Übergabe an K."], ["K trägt den Schaden, weil die Gefahr bei der Holschuld mit Vertragsschluss übergeht.", "Falsch. Die Gefahr geht mit der Übergabe über (§ 446)."], ["K hat nur deliktische Ansprüche gegen den Verkäufer persönlich.", "Falsch. Vertragliche Mängelrechte bestehen gegen H."], ["Der Laptop war bei Gefahrübergang mangelhaft; K hat die Rechte aus § 437.", "Richtig. Schaden vor bzw. bei Übergabe, also vor Gefahrübergang."], ["K hat seine Rechte verloren, weil er den Laptop trotz des Sprungs mitgenommen hat.", "Falsch. Die Kenntnis bei Übergabe schadet nicht (§ 442 betrifft den Vertragsschluss)."], ["K kann nur mindern, weil er den Laptop in Kenntnis des Schadens angenommen hat.", "Falsch. Eine solche Beschränkung gibt es nicht."]], "id": "P2-kauf3-9"}, {"topic": "kauf", "sv": "Verbraucher K kauft beim Händler H ein Mountainbike für 1.500 €. Wegen eines Rahmenbruchs stürzt K nach drei Wochen und beschädigt dabei sein Handy (Schaden 400 €). H hatte den Rahmen bei der Übergabeinspektion trotz sichtbarer Risse nicht beanstandet.", "q": "Welche Ansprüche hat K wegen des Handys?", "c": 2, "o": [["Keine, weil das Handy nicht Gegenstand des Kaufvertrags war.", "Falsch. Mangelfolgeschäden an anderen Rechtsgütern sind nach § 280 I ersatzfähig."], ["400 €, aber erst nach erfolgloser Frist zur Nacherfüllung (§ 281).", "Falsch. Der Folgeschaden ist durch Nacherfüllung nicht zu beseitigen; keine Frist nötig."], ["400 € als Schadensersatz neben der Leistung (§§ 437 Nr. 3, 280 I).", "Richtig. Mangelfolgeschaden, Vertretenmüssen."], ["400 € nur nach dem ProdHaftG gegen den Hersteller.", "Falsch. Daneben besteht ein vertraglicher Anspruch gegen H."], ["400 € nur, wenn H die Risse vorsätzlich übersehen hat.", "Falsch. Fahrlässigkeit genügt."], ["400 € als Minderung des Kaufpreises.", "Falsch. Die Minderung betrifft den Wert der Kaufsache, nicht Folgeschäden."]], "id": "P2-kauf3-10"}, {"topic": "kauf", "sv": "K kauft beim Kunsthändler H ein Gemälde, das beide für ein Werk des Malers M halten. Es stellt sich heraus, dass es eine Kopie ist. K will den Kaufvertrag wegen Eigenschaftsirrtums anfechten.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["K kann nach § 119 II anfechten, weil die Urheberschaft eine verkehrswesentliche Eigenschaft ist.", "Falsch. Nach Gefahrübergang verdrängt das Mängelrecht die Anfechtung nach § 119 II."], ["K kann wählen, ob er anficht oder Mängelrechte geltend macht.", "Falsch. Das Mängelrecht hat Vorrang."], ["K hat keine Rechte, weil beide Parteien sich gleich geirrt haben.", "Falsch. Der Doppelirrtum hindert die Mängelrechte nicht."], ["K kann nur nach § 313 eine Anpassung verlangen, weil beide sich über die Grundlage geirrt haben.", "Falsch. Die Mängelrechte gehen § 313 vor."], ["K kann nach § 123 anfechten, weil H die Echtheit behauptet hat.", "Falsch. H war gutgläubig; eine arglistige Täuschung liegt nicht vor."], ["§ 119 II ist ausgeschlossen; K hat Mängelrechte, weil die Urheberschaft vereinbarte Beschaffenheit war.", "Richtig. Vorrang des Mängelrechts nach Gefahrübergang."]], "id": "P2-kauf3-11"}, {"topic": "kauf", "sv": "Verbraucher K kauft beim Händler H eine Fritteuse. Ein Defekt zeigt sich. K verlangt Neulieferung; H liefert eine neue Fritteuse, die denselben Defekt hat, und erklärt, ein weiterer Austausch komme nicht in Frage.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["K muss H noch einmal eine Frist zur Neulieferung setzen, weil eine Ersatzlieferung immer zwei Versuche erlaubt.", "Falsch. Die Regel des § 440 S. 2 betrifft die Nachbesserung; hier ist die Nacherfüllung jedenfalls fehlgeschlagen."], ["Die Nacherfüllung ist fehlgeschlagen; K kann zurücktreten oder mindern.", "Richtig. Ersatzlieferung mit demselben Mangel."], ["K hat seine Rechte verbraucht, weil er Neulieferung gewählt hat.", "Falsch. Bei fehlgeschlagener Nacherfüllung bleiben die weiteren Rechte."], ["K kann nur mindern, weil die neue Fritteuse funktioniert, solange der Defekt nicht auftritt.", "Falsch. Die Ersatzsache ist ebenso mangelhaft."], ["K hat keine Rechte, weil H rechtzeitig nacherfüllt hat.", "Falsch. Eine mangelhafte Ersatzlieferung ist keine Erfüllung."], ["K kann nur Schadensersatz verlangen, weil der Rücktritt nach einer Ersatzlieferung ausgeschlossen ist.", "Falsch. Einen solchen Ausschluss gibt es nicht."]], "id": "P2-kauf3-12"}, {"topic": "kauf", "sv": "Verbraucherin V kauft im Supermarkt eine Packung Joghurt. Zu Hause stellt sie fest, dass er schon verschimmelt ist, obwohl das Mindesthaltbarkeitsdatum noch nicht erreicht ist.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Mangelhaft; V kann Nacherfüllung durch einen neuen Joghurt verlangen.", "Richtig. Keine Eignung zur gewöhnlichen Verwendung. (§§ 434, 439)"], ["V hat keine Rechte, weil Lebensmittel vom Gewährleistungsrecht ausgenommen sind.", "Falsch. Auch Lebensmittel sind Waren."], ["V kann nur widerrufen, weil der Joghurt schnell verdirbt.", "Falsch. Im Laden gibt es kein Widerrufsrecht; Mängelrechte bestehen aber."], ["V muss sich an den Hersteller halten, weil der Supermarkt den Joghurt nicht hergestellt hat.", "Falsch. Mängelrechte richten sich gegen den Verkäufer."], ["V kann nur Schadensersatz verlangen, weil Nacherfüllung bei Lebensmitteln unmöglich ist.", "Falsch. Eine Ersatzlieferung ist ohne Weiteres möglich."], ["V hat Rechte nur, wenn sie den Kassenbon vorlegt.", "Falsch. Der Bon ist ein Beweismittel, keine Anspruchsvoraussetzung."]], "id": "P2-kauf3-13"}, {"topic": "kauf", "sv": "K kauft vom Privatmann P einen gebrauchten Pkw. Im Vertrag steht: „Das Fahrzeug ist unfallfrei.“ P glaubte das wirklich. Tatsächlich hatte der Wagen einen reparierten Frontschaden. Außerdem steht im Vertrag: „Gewährleistung ausgeschlossen.“", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["K hat keine Rechte, weil die Gewährleistung zwischen Privatleuten wirksam ausgeschlossen ist.", "Falsch. Ein Ausschluss erfasst nach der Rechtsprechung nicht die ausdrücklich vereinbarte Beschaffenheit."], ["K hat Rechte nur, wenn P den Unfall arglistig verschwiegen hat (§ 444).", "Falsch. Die vereinbarte Beschaffenheit wird vom pauschalen Ausschluss nicht erfasst."], ["K kann nur anfechten, weil der Ausschluss alle Mängelrechte sperrt.", "Falsch. Der Ausschluss sperrt gerade die vereinbarte Beschaffenheit nicht."], ["Der gesamte Kaufvertrag ist nichtig, weil zwei Klauseln sich widersprechen.", "Falsch. Die Klauseln werden durch Auslegung miteinander in Einklang gebracht."], ["K hat Mängelrechte; der pauschale Ausschluss erfasst die vereinbarte Unfallfreiheit nicht.", "Richtig. Beschaffenheitsvereinbarung geht vor (BGH)."], ["K hat Rechte nur, wenn P eine Garantie im Sinne des § 443 übernommen hat.", "Falsch. Eine Beschaffenheitsvereinbarung genügt."]], "id": "P2-kauf3-14"}];
L.forEach(q=>{ if(!W.some(x=>x.id===q.id)) W.push(q); });
window.dispatchEvent(new Event('wpr-data'));
})();
